73	fn generate_glm52_trtllm_fmha_cubins(root: &Path, out_dir: &Path) {
74	    let cubin_dir = root.join("cubin/glm52");
75	    let mut generated = String::from(
76	        "// Generated by pegainfer-kernels/build.rs from the checked-in FlashInfer cubins.\n\
77	         #pragma once\n\n",
78	    );
79	    for &(symbol, file_name) in GLM52_TRTLLM_FMHA_CUBINS {
80	        let path = cubin_dir.join(file_name);
81	        println!("cargo:rerun-if-changed={}", path.display());
82	        let bytes = fs::read(&path).unwrap_or_else(|err| {
83	            panic!(
84	                "failed to read GLM5.2 TRTLLM FMHA cubin {}: {err}",
85	                path.display()
86	            )
87	        });
88	        writeln!(&mut generated, "static const unsigned char {symbol}[] = {{")
89	            .expect("write cubin array declaration");
90	        for chunk in bytes.chunks(16) {
91	            generated.push_str("  ");
92	            for byte in chunk {
93	                write!(&mut generated, "0x{byte:02x}, ").expect("write cubin byte");
94	            }
95	            generated.push('\n');
96	        }
97	        generated.push_str("};\n");
98	        writeln!(
99	            &mut generated,
100	            "static constexpr unsigned int {symbol}Size = sizeof({symbol});\n"
101	        )
102	        .expect("write cubin array size");
103	    }
104	    let output = out_dir.join("glm52_trtllm_fmha_cubins.inc");
105	    fs::write(&output, generated).unwrap_or_else(|err| {
106	        panic!(
107	            "failed to write generated GLM5.2 TRTLLM FMHA cubin header {}: {err}",
108	            output.display()
109	        )
110	    });
111	}
