117	/// AOT-export the CuTe DSL tcgen05 fp8 GEMMs and compile the dispatch shim
118	/// around them (csrc/glm52/glm52_fp8_dsl_gemm.c). Opt-in via
119	/// `PEGAINFER_CUTEDSL_PYTHON` (a Python with torch + nvidia-cutlass-dsl on a
120	/// CUDA box); without it the shim compiles as an empty-table stub and the
121	/// runtime stays on the CUTLASS route. The exported objects resolve their
122	/// `_cuda*` wrapper symbols from the DSL wheel's libcute_dsl_runtime.so —
123	/// linked here, needed on LD_LIBRARY_PATH at run time.
124	fn build_glm52_cutedsl_fp8_dsl(root: &Path, out_dir: &Path, cuda_include: &Path) {
125	    println!("cargo:rerun-if-env-changed=PEGAINFER_CUTEDSL_PYTHON");
126	    let shim_c = root.join("csrc/glm52/glm52_fp8_dsl_gemm.c");
127	    println!("cargo:rerun-if-changed={}", shim_c.display());
128	    let mut shim = cc::Build::new();
129	    shim.include(cuda_include)
130	        .flag("-std=c11")
131	        .warnings(false)
132	        .file(&shim_c);
133	    if let Ok(python) = std::env::var("PEGAINFER_CUTEDSL_PYTHON") {
134	        let script = root.join("tools/cutedsl/export_glm52_fp8_dsl.py");
135	        let benches = workspace_root().join("pegainfer-glm52/benches");
136	        let gen_dir = out_dir.join("cutedsl_fp8_dsl");
137	        fs::create_dir_all(&gen_dir).expect("create the cutedsl gen dir");
138	        println!("cargo:rerun-if-changed={}", script.display());
139	        for source in [
140	            "kernel_lab/units/fp8_gemm_dsl_tc_kernel.py",
141	            "kernel_lab/units/fp8_gemm_dsl_tc.py",
142	        ] {
143	            println!("cargo:rerun-if-changed={}", benches.join(source).display());
144	        }
145	        let status = time_phase("cutedsl fp8 GEMM export", || {
146	            Command::new(&python)
147	                .arg(&script)
148	                .arg("--benches-dir")
149	                .arg(&benches)
150	                .arg("--out-dir")
151	                .arg(&gen_dir)
152	                .status()
153	        })
154	        .unwrap_or_else(|err| panic!("failed to run {python}: {err}"));
155	        assert!(
156	            status.success(),
157	            "CuTe DSL fp8 GEMM export failed (PEGAINFER_CUTEDSL_PYTHON={python})"
158	        );
159	        let mut objects: Vec<PathBuf> = fs::read_dir(&gen_dir)
160	            .expect("read the cutedsl gen dir")
161	            .filter_map(|entry| {
162	                let path = entry.ok()?.path();
163	                (path.extension().and_then(|e| e.to_str()) == Some("o")).then_some(path)
164	            })
165	            .collect();
166	        objects.sort();
167	        assert!(!objects.is_empty(), "cutedsl export produced no objects");
168	        let object_count = objects.len();
169	        for object in objects {
170	            shim.object(object);
171	        }
172	        shim.define("GLM52_CUTEDSL_AOT", None).include(&gen_dir);
173	        let lib_dir_probe = Command::new(&python)
174	            .args([
175	                "-c",
176	                "import cutlass, os; print(os.path.abspath(os.path.join(os.path.dirname(cutlass.__file__), '..', '..', 'lib')))",
177	            ])
178	            .output()
179	            .expect("probe the nvidia-cutlass-dsl lib dir");
180	        let lib_dir = String::from_utf8_lossy(&lib_dir_probe.stdout)
181	            .trim()
182	            .to_string();
183	        assert!(
184	            Path::new(&lib_dir).join("libcute_dsl_runtime.so").exists(),
185	            "libcute_dsl_runtime.so not found under {lib_dir}"
186	        );
187	        println!("cargo:rustc-link-search=native={lib_dir}");
188	        println!("cargo:rustc-link-lib=dylib=cute_dsl_runtime");
189	        println!(
190	            "cargo:warning=GLM5.2 CuTe DSL fp8 GEMM AOT enabled: {object_count} objects; \
191	             libcute_dsl_runtime.so ({lib_dir}) must be on LD_LIBRARY_PATH at run time"
192	        );
193	    }
194	    time_phase("cc glm52_fp8_dsl_gemm", || {
195	        shim.compile("glm52_fp8_dsl_gemm");
196	    });
197	}
