203	fn ensure_git_submodules_initialized(repo_root: &Path) {
204	    if !repo_root.join(".git").exists() || !repo_root.join(".gitmodules").is_file() {
205	        return;
206	    }
207	
208	    println!(
209	        "cargo:rerun-if-changed={}",
210	        repo_root.join(".gitmodules").display()
211	    );
212	
213	    let output = Command::new("git")
214	        .args(["submodule", "status", "--recursive"])
215	        .current_dir(repo_root)
216	        .output()
217	        .unwrap_or_else(|err| {
218	            panic!(
219	                "Failed to inspect git submodules from {}: {err}. \
220	                 Install git or run `git submodule update --init --recursive` manually.",
221	                repo_root.display()
222	            )
223	        });
224	    assert!(
225	        output.status.success(),
226	        "Failed to inspect git submodules from {}. stdout: {} stderr: {}",
227	        repo_root.display(),
228	        String::from_utf8_lossy(&output.stdout).trim(),
229	        String::from_utf8_lossy(&output.stderr).trim()
230	    );
231	
232	    if !String::from_utf8_lossy(&output.stdout)
233	        .lines()
234	        .any(|line| line.starts_with('-'))
235	    {
236	        return;
237	    }
238	
239	    println!("cargo:warning=Initializing missing git submodules for first build");
240	    let output = Command::new("git")
241	        .args(["submodule", "update", "--init", "--recursive"])
242	        .current_dir(repo_root)
243	        .output()
244	        .unwrap_or_else(|err| {
245	            panic!(
246	                "Failed to initialize git submodules from {}: {err}. \
247	                 Run `git submodule update --init --recursive` manually.",
248	                repo_root.display()
249	            )
250	        });
251	    assert!(
252	        output.status.success(),
253	        "Failed to initialize git submodules from {}. stdout: {} stderr: {}",
254	        repo_root.display(),
255	        String::from_utf8_lossy(&output.stdout).trim(),
256	        String::from_utf8_lossy(&output.stderr).trim()
257	    );
258	}
