314	fn parse_sm_token(raw: &str) -> Option<String> {
315	    let token = raw.trim().trim_matches('"');
316	    if token.is_empty() {
317	        return None;
318	    }
319	
320	    let token = token
321	        .strip_prefix("sm_")
322	        .or_else(|| token.strip_prefix("compute_"))
323	        .unwrap_or(token);
324	
325	    if let Some((major, minor)) = token.split_once('.') {
326	        let digit_count = minor.chars().take_while(char::is_ascii_digit).count();
327	        let (minor_digits, suffix) = minor.split_at(digit_count);
328	        if major.chars().all(|c| c.is_ascii_digit())
329	            && !minor_digits.is_empty()
330	            && suffix.chars().all(|c| c.is_ascii_alphabetic())
331	        {
332	            return Some(format!("{major}{minor_digits}{suffix}"));
333	        }
334	        return None;
335	    }
336	
337	    let digit_count = token.chars().take_while(char::is_ascii_digit).count();
338	    let (digits, suffix) = token.split_at(digit_count);
339	    if !digits.is_empty() && suffix.chars().all(|c| c.is_ascii_alphabetic()) {
340	        if digits.len() == 1 {
341	            return Some(format!("{digits}0{suffix}"));
342	        }
343	        return Some(format!("{digits}{suffix}"));
344	    }
345	
346	    None
347	}
