365	fn normalize_nvcc_sm(sm: &str, supported_arches: Option<&BTreeSet<String>>) -> String {
366	    let preferred = match sm {
367	        "120" | "120f" => Some("120f"),
368	        "121" | "121a" => Some("121a"),
369	        _ => None,
370	    };
371	    if let Some(preferred) = preferred {
372	        if supported_arches.is_some_and(|arches| arches.contains(&format!("compute_{preferred}"))) {
373	            return preferred.to_string();
374	        }
375	        let raw = sm_numeric_prefix(sm).map_or_else(|| sm.to_string(), |sm| sm.to_string());
376	        println!(
377	            "cargo:warning=nvcc does not list compute_{preferred}; compiling CUDA kernels for raw sm_{raw}"
378	        );
379	        return raw;
380	    }
381	    sm.to_string()
382	}
