392	fn sm_targets_from_nvidia_smi() -> Option<Vec<String>> {
393	    let output = Command::new("nvidia-smi")
394	        .args(["--query-gpu=compute_cap", "--format=csv,noheader"])
395	        .output()
396	        .ok()?;
397	    if !output.status.success() {
398	        return None;
399	    }
400	
401	    let stdout = String::from_utf8_lossy(&output.stdout);
402	    let mut sms = BTreeSet::new();
403	    for line in stdout.lines() {
404	        let cap = line.split(',').next().unwrap_or(line).trim();
405	        if let Some(sm) = parse_sm_token(cap) {
406	            sms.insert(sm);
407	        }
408	    }
409	
410	    if sms.is_empty() {
411	        None
412	    } else {
413	        Some(sms.into_iter().collect())
414	    }
415	}
