467	fn nvcc_accepts_gencode(nvcc: &str, compute: &str, sm: &str) -> bool {
468	    let stem = format!(
469	        "pegainfer_nvcc_probe_{}_compute_{compute}_sm_{sm}",
470	        std::process::id()
471	    );
472	    let cu_path = std::env::temp_dir().join(format!("{stem}.cu"));
473	    let obj_path = std::env::temp_dir().join(format!("{stem}.o"));
474	    if let Err(err) = fs::write(
475	        &cu_path,
476	        "extern \"C\" __global__ void pegainfer_nvcc_probe() {}\n",
477	    ) {
478	        println!(
479	            "cargo:warning=Failed to write nvcc probe {}: {err}",
480	            cu_path.display()
481	        );
482	        return false;
483	    }
484	
485	    let output = Command::new(nvcc)
486	        .args(["-c"])
487	        .arg(&cu_path)
488	        .arg("-o")
489	        .arg(&obj_path)
490	        .arg("-gencode")
491	        .arg(format!("arch=compute_{compute},code=sm_{sm}"))
492	        .output();
493	    let _ = fs::remove_file(&cu_path);
494	    let _ = fs::remove_file(&obj_path);
495	
496	    match output {
497	        Ok(output) if output.status.success() => true,
498	        Ok(output) => {
499	            println!(
500	                "cargo:warning=nvcc rejected compute_{compute}/sm_{sm} probe: {}",
501	                String::from_utf8_lossy(&output.stderr).trim()
502	            );
503	            false
504	        }
505	        Err(err) => {
506	            println!("cargo:warning=Failed to run nvcc arch probe: {err}");
507	            false
508	        }
509	    }
510	}
