512	fn glm52_fp8_gemm_arch_args(normalized_sms: &[String], nvcc: &str) -> Option<Vec<String>> {
513	    let mut args = Vec::new();
514	    for sm in normalized_sms {
515	        let numeric = sm_numeric_prefix(sm)?;
516	        if !(100..120).contains(&numeric) {
517	            continue;
518	        }
519	        let accelerated = format!("{numeric}a");
520	        if !nvcc_accepts_gencode(nvcc, &accelerated, &accelerated) {
521	            continue;
522	        }
523	        args.push("-gencode".to_string());
524	        args.push(format!("arch=compute_{accelerated},code=sm_{accelerated}"));
525	    }
526	    (!args.is_empty()).then_some(args)
527	}
