529	fn glm52_flashmla_sparse_arch_args(normalized_sms: &[String], nvcc: &str) -> Vec<String> {
530	    let sm90a_supported = normalized_sms.iter().any(|sm| sm == "90" || sm == "90a")
531	        && nvcc_accepts_gencode(nvcc, "90a", "90a");
532	    let sm100f_supported = normalized_sms
533	        .iter()
534	        .any(|sm| sm_numeric_prefix(sm).is_some_and(|n| (100..120).contains(&n)))
535	        && nvcc_accepts_gencode(nvcc, "100f", "100f");
536	
537	    let mut targets = Vec::new();
538	    for sm in normalized_sms {
539	        let target = match sm_numeric_prefix(sm) {
540	            Some(90) => {
541	                if sm90a_supported {
542	                    Some(("90a", "90a", "sm_90a"))
543	                } else {
544	                    println!(
545	                        "cargo:warning=nvcc cannot compile compute_90a/sm_90a; GLM5.2 FlashMLA sparse decode will use sm_{sm}"
546	                    );
547	                    Some((sm.as_str(), sm.as_str(), "native"))
548	                }
549	            }
550	            Some(100..=119) => {
551	                if sm100f_supported {
552	                    Some(("100f", "100f", "sm_100f"))
553	                } else {
554	                    println!(
555	                        "cargo:warning=nvcc cannot compile compute_100f/sm_100f; GLM5.2 FlashMLA sparse decode will use sm_{sm}"
556	                    );
557	                    Some((sm.as_str(), sm.as_str(), "native"))
558	                }
559	            }
560	            _ => Some((sm.as_str(), sm.as_str(), "native")),
561	        };
562	        if let Some(target) = target {
563	            if !targets.iter().any(|existing| existing == &target) {
564	                targets.push(target);
565	            }
566	        }
567	    }
568	
569	    let labels = targets
570	        .iter()
571	        .map(|(_, sm, label)| {
572	            if *label == "native" {
573	                format!("sm_{sm}")
574	            } else {
575	                label.to_string()
576	            }
577	        })
578	        .collect::<Vec<_>>();
579	    if labels
580	        != normalized_sms
581	            .iter()
582	            .map(|sm| format!("sm_{sm}"))
583	            .collect::<Vec<_>>()
584	    {
585	        println!(
586	            "cargo:warning=Compiling GLM5.2 FlashMLA sparse decode for nvcc targets: {}",
587	            labels.join(",")
588	        );
589	    }
590	
591	    let mut args = Vec::new();
592	    for (compute, sm, _) in targets {
593	        args.push("-gencode".to_string());
594	        args.push(format!("arch=compute_{compute},code=sm_{sm}"));
595	    }
596	    args
597	}
