646	/// FlashKDA (vendored, third_party/flash-kda) is SM90 TMA + cluster barriers,
647	/// portable across the accelerated (`a`) variants — upstream supports
648	/// 90a/100a/103a/120a with one code path. Compile the accelerated variant of
649	/// every requested target that nvcc accepts; `None` means no target can carry
650	/// the kernel and the TU falls back to its NOT_SUPPORTED stub.
651	fn k3_flash_kda_arch_args(normalized_sms: &[String], nvcc: &str) -> Option<Vec<String>> {
652	    let mut args = Vec::new();
653	    for sm in normalized_sms {
654	        let Some(numeric) = sm_numeric_prefix(sm) else {
655	            continue;
656	        };
657	        if numeric < 90 {
658	            continue;
659	        }
660	        let accelerated = format!("{numeric}a");
661	        if !nvcc_accepts_gencode(nvcc, &accelerated, &accelerated) {
662	            continue;
663	        }
664	        args.push("-gencode".to_string());
665	        args.push(format!("arch=compute_{accelerated},code=sm_{accelerated}"));
666	    }
667	    (!args.is_empty()).then_some(args)
668	}
