671	fn collect_files_recursively(dir: &Path, out: &mut Vec<PathBuf>) {
672	    let mut entries: Vec<_> = std::fs::read_dir(dir)
673	        .unwrap_or_else(|err| panic!("Failed to read {}: {err}", dir.display()))
674	        .map(|entry| {
675	            entry.unwrap_or_else(|err| panic!("Failed to read entry in {}: {err}", dir.display()))
676	        })
677	        .collect();
678	    entries.sort_by_key(std::fs::DirEntry::path);
679	
680	    for entry in entries {
681	        let path = entry.path();
682	        if path.is_dir() {
683	            collect_files_recursively(&path, out);
684	        } else {
685	            out.push(path);
686	        }
687	    }
688	}
