813	/// NCCL >= 2.30.4 root (include/nccl.h + lib/libnccl.so.2) for the DeepEP
814	/// shim's device API (ncclDevComm / windows / GIN). cudarc dlopens whatever
815	/// libnccl.so.2 it finds at runtime, so build and runtime must point at the
816	/// same install: set PEGAINFER_NCCL_ROOT and put `$PEGAINFER_NCCL_ROOT/lib`
817	/// on LD_LIBRARY_PATH. The nvidia-nccl-cu13 wheel layout works directly:
818	///   pip download 'nvidia-nccl-cu13>=2.30.4' --no-deps -d /tmp/nccl \
819	///     && unzip /tmp/nccl/*.whl 'nvidia/nccl/*' -d /tmp/nccl \
820	///     && export PEGAINFER_NCCL_ROOT=/tmp/nccl/nvidia/nccl
821	fn deepep_nccl_root() -> PathBuf {
822	    let Ok(root) = std::env::var("PEGAINFER_NCCL_ROOT").map(PathBuf::from) else {
823	        panic!(
824	            "The moe feature builds the DeepEP shim, which needs NCCL >= 2.30.4. \
825	             Set PEGAINFER_NCCL_ROOT to an install with include/nccl.h and lib/libnccl.so.2 \
826	             (e.g. the unpacked nvidia-nccl-cu13 wheel)."
827	        )
828	    };
829	
830	    let header = root.join("include/nccl.h");
831	    let contents = fs::read_to_string(&header).unwrap_or_else(|err| {
832	        panic!(
833	            "PEGAINFER_NCCL_ROOT: cannot read {}: {err}",
834	            header.display()
835	        )
836	    });
837	    let version_component = |name: &str| -> u32 {
838	        contents
839	            .lines()
840	            .find_map(|line| line.strip_prefix(&format!("#define {name} ")))
841	            .and_then(|value| value.trim().parse().ok())
842	            .unwrap_or_else(|| panic!("{} does not define {name}", header.display()))
843	    };
844	    let version = version_component("NCCL_MAJOR") * 10000
845	        + version_component("NCCL_MINOR") * 100
846	        + version_component("NCCL_PATCH");
847	    assert!(
848	        version >= 23004,
849	        "PEGAINFER_NCCL_ROOT points at NCCL {version} (< 2.30.4); the DeepEP shim needs the \
850	         NCCL device API"
851	    );
852	
853	    let lib = root.join("lib/libnccl.so.2");
854	    assert!(
855	        lib.is_file(),
856	        "PEGAINFER_NCCL_ROOT: {} not found",
857	        lib.display()
858	    );
859	    root
860	}
