862	/// The wheel ships only libnccl.so.2; give the linker the unversioned name it
863	/// wants via a symlink in OUT_DIR (already on the link search path). The
864	/// resulting DT_NEEDED is the soname (libnccl.so.2), resolved at runtime from
865	/// LD_LIBRARY_PATH.
866	fn link_deepep_nccl(nccl_root: &Path, out_dir: &Path) {
867	    let link_name = out_dir.join("libnccl.so");
868	    let target = nccl_root.join("lib/libnccl.so.2");
869	    match fs::read_link(&link_name) {
870	        Ok(existing) if existing == target => {}
871	        _ => {
872	            let _ = fs::remove_file(&link_name);
873	            std::os::unix::fs::symlink(&target, &link_name)
874	                .unwrap_or_else(|err| panic!("Failed to symlink {}: {err}", link_name.display()));
875	        }
876	    }
877	    println!("cargo:rustc-link-lib=dylib=nccl");
878	}
