880	/// Link the freshly compiled CUDA objects into `libglm52_kernel_lab.so` for
881	/// the kernel-lab Python harness (`PEGAINFER_KERNEL_LAB=1` only). The objects
882	/// are already PIC (every nvcc task adds `--compiler-options -fPIC`), so the
883	/// same .o files that feed `libkernels_cuda.a` link into a shared object
884	/// without a second compile pass. DeepEP shim objects reference NCCL symbols
885	/// that stay unresolved in the .so — the harness dlopens with `RTLD_LAZY` and
886	/// never calls into DeepEP for these units.
887	fn link_kernel_lab_shared(
888	    nvcc: &str,
889	    toolkit: &pegainfer_build::CudaToolkit,
890	    out_dir: &Path,
891	    obj_files: &[PathBuf],
892	) {
893	    let so_path = out_dir.join("libglm52_kernel_lab.so");
894	    let _ = fs::remove_file(&so_path);
895	    let mut args = vec!["-shared".to_string()];
896	    args.extend(
897	        obj_files
898	            .iter()
899	            .map(|path| path.to_string_lossy().to_string()),
900	    );
901	    args.extend([
902	        "-o".to_string(),
903	        so_path.to_string_lossy().to_string(),
904	        format!("-L{}", toolkit.root.join("lib64").display()),
905	        "-lcudart".to_string(),
906	        "-lcublas".to_string(),
907	        "-lcublasLt".to_string(),
908	        "-lnvrtc".to_string(),
909	        "-lcuda".to_string(),
910	        "-lstdc++".to_string(),
911	    ]);
912	    let status = time_phase("nvcc -shared libglm52_kernel_lab.so", || {
913	        Command::new(nvcc)
914	            .args(&args)
915	            .status()
916	            .expect("Failed to run nvcc for libglm52_kernel_lab.so")
917	    });
918	    assert!(status.success(), "kernel-lab shared link failed");
919	
920	    // Stable discovery path: OUT_DIR is target/<profile>/build/<pkg>-<hash>/out,
921	    // so three parents up is target/<profile>.
922	    if let Some(profile_dir) = out_dir
923	        .parent()
924	        .and_then(Path::parent)
925	        .and_then(Path::parent)
926	    {
927	        let stable = profile_dir.join("libglm52_kernel_lab.so");
928	        fs::copy(&so_path, &stable).unwrap_or_else(|err| {
929	            panic!(
930	                "Failed to copy kernel-lab .so to {}: {err}",
931	                stable.display()
932	            )
933	        });
934	        println!("cargo:warning=kernel_lab .so: {}", stable.display());
935	    } else {
936	        println!(
937	            "cargo:warning=kernel_lab .so: {} (no stable target/<profile> copy)",
938	            so_path.display()
939	        );
940	    }
941	}
