943	fn cuda_object_name(csrc_dir: &Path, cu_file: &Path) -> String {
944	    let Some(relative) = cu_file.strip_prefix(csrc_dir).ok() else {
945	        return format!("{}_cuda.o", cu_file.file_stem().unwrap().to_string_lossy());
946	    };
947	
948	    let mut parts: Vec<String> = relative
949	        .components()
950	        .filter_map(|component| component.as_os_str().to_str().map(ToOwned::to_owned))
951	        .collect();
952	    if let Some(last) = parts.last_mut() {
953	        if let Some(stem) = Path::new(last).file_stem().and_then(|stem| stem.to_str()) {
954	            *last = stem.to_string();
955	        }
956	    }
957	
958	    format!("{}_cuda.o", parts.join("_"))
959	}
