977	fn find_triton_python() -> Result<String, String> {
978	    if let Ok(candidate) = std::env::var("PEGAINFER_TRITON_PYTHON") {
979	        let candidate = candidate.trim();
980	        if candidate.is_empty() {
981	            return Err(
982	                "PEGAINFER_TRITON_PYTHON is set but empty. See pegainfer-kernels/tools/triton/README.md.".to_string(),
983	            );
984	        }
985	        return probe_triton_python(candidate).map_err(|message| {
986	            format!(
987	                "PEGAINFER_TRITON_PYTHON=`{candidate}` could not import Triton. {message}. See pegainfer-kernels/tools/triton/README.md."
988	            )
989	        });
990	    }
991	
992	    let local_venv = workspace_root().join(".venv/bin/python");
993	    let mut diagnostics = Vec::new();
994	    let mut candidates = Vec::new();
995	    if local_venv.exists() {
996	        candidates.push(local_venv.to_string_lossy().to_string());
997	    }
998	    candidates.extend(["python3".to_string(), "python".to_string()]);
999	
1000	    for candidate in candidates {
1001	        match probe_triton_python(&candidate) {
1002	            Ok(path) => return Ok(path),
1003	            Err(message) => diagnostics.push(message),
1004	        }
1005	    }
1006	
1007	    Err(format!(
1008	        "Could not find a Python interpreter with Triton installed. Set PEGAINFER_TRITON_PYTHON, bootstrap .venv, or ensure `python3 -c 'import triton'` works. Probe results: {}.",
1009	        diagnostics.join(" | ")
1010	    ))
1011	}
