1137	fn generate_triton_artifacts(
1138	    python: &str,
1139	    out_dir: &Path,
1140	    triton_target: &str,
1141	    spec: &TritonKernelSpec,
1142	) -> (String, PathBuf) {
1143	    let root = crate_root();
1144	    let generator_path = root.join("tools/triton/gen_triton_aot.py");
1145	    let artifact_dir = out_dir.join("triton_aot").join(spec.artifact_dir);
1146	
1147	    let output = time_phase(format!("triton-gen {}", spec.kernel_name), || {
1148	        Command::new(python)
1149	            .arg(&generator_path)
1150	            .arg("--kernel-path")
1151	            .arg(root.join(spec.kernel_path))
1152	            .arg("--kernel-name")
1153	            .arg(spec.kernel_name)
1154	            .arg("--signature")
1155	            .arg(spec.signature)
1156	            .arg("--grid")
1157	            .arg(spec.grid)
1158	            .arg("--out-name")
1159	            .arg(spec.out_name)
1160	            .arg("--out-dir")
1161	            .arg(&artifact_dir)
1162	            .arg("--target")
1163	            .arg(triton_target)
1164	            .arg("--num-warps")
1165	            .arg(spec.num_warps.to_string())
1166	            .arg("--num-stages")
1167	            .arg(spec.num_stages.to_string())
1168	            .output()
1169	            .unwrap_or_else(|err| {
1170	                panic!(
1171	                    "failed to run Triton AOT generator for {}: {err}",
1172	                    spec.kernel_name
1173	                )
1174	            })
1175	    });
1176	
1177	    assert!(
1178	        output.status.success(),
1179	        "Triton AOT generator failed for {}. stdout: {} stderr: {}",
1180	        spec.kernel_name,
1181	        String::from_utf8_lossy(&output.stdout).trim(),
1182	        String::from_utf8_lossy(&output.stderr).trim(),
1183	    );
1184	
1185	    let stdout = String::from_utf8_lossy(&output.stdout);
1186	    let mut func_name = None;
1187	    let mut c_path = None;
1188	    for line in stdout.lines() {
1189	        if let Some(value) = line.strip_prefix("FUNC_NAME=") {
1190	            func_name = Some(value.trim().to_string());
1191	        } else if let Some(value) = line.strip_prefix("C_PATH=") {
1192	            c_path = Some(PathBuf::from(value.trim()));
1193	        }
1194	    }
1195	
1196	    let func_name = func_name.expect("Triton generator did not print FUNC_NAME");
1197	    let c_path = c_path.expect("Triton generator did not print C_PATH");
1198	    patch_triton_aot_per_device_handles(&c_path);
1199	    (func_name, c_path)
1200	}
