1202	fn patch_triton_aot_per_device_handles(c_path: &Path) {
1203	    let src = fs::read_to_string(c_path).expect("failed to read generated Triton C source");
1204	    let module_name = src
1205	        .lines()
1206	        .find_map(|line| line.strip_prefix("CUmodule "))
1207	        .and_then(|rest| rest.strip_suffix(" = NULL;"))
1208	        .map(str::to_string)
1209	        .expect("generated Triton C source should declare one CUmodule");
1210	    let function_name = src
1211	        .lines()
1212	        .find_map(|line| line.strip_prefix("CUfunction "))
1213	        .and_then(|rest| rest.strip_suffix(" = NULL;"))
1214	        .map(str::to_string)
1215	        .expect("generated Triton C source should declare one CUfunction");
1216	
1217	    let device_table_define = "#define PEGAINFER_TRITON_DEVICE_TABLE_SIZE 16\n\n";
1218	    let device_helper = "\n\nstatic CUresult pegainfer_triton_current_device(CUdevice *dev) {\n  CUresult err = cuCtxGetDevice(dev);\n  if (err != CUDA_SUCCESS) {\n    return err;\n  }\n  if (*dev < 0 || *dev >= PEGAINFER_TRITON_DEVICE_TABLE_SIZE) {\n    return CUDA_ERROR_INVALID_DEVICE;\n  }\n  return CUDA_SUCCESS;\n}";
1219	
1220	    let patched = src
1221	        .replace(
1222	            &format!("CUmodule {module_name} = NULL;"),
1223	            &format!(
1224	                "{device_table_define}CUmodule {module_name}[PEGAINFER_TRITON_DEVICE_TABLE_SIZE] = {{0}};"
1225	            ),
1226	        )
1227	        .replace(
1228	            &format!("CUfunction {function_name} = NULL;"),
1229	            &format!(
1230	                "CUfunction {function_name}[PEGAINFER_TRITON_DEVICE_TABLE_SIZE] = {{0}};{device_helper}"
1231	            ),
1232	        )
1233	        .replace(
1234	            &format!("CUDA_CHECK(cuModuleUnload({module_name}));"),
1235	            &format!(
1236	                "CUdevice dev = 0;\n    CUDA_CHECK(pegainfer_triton_current_device(&dev));\n    if ({module_name}[dev] != NULL) {{\n      CUDA_CHECK(cuModuleUnload({module_name}[dev]));\n      {module_name}[dev] = NULL;\n      {function_name}[dev] = NULL;\n    }}"
1237	            ),
1238	        );
1239	    let patched = patched
1240	        .replace(
1241	            &format!("cuModuleLoadData(&{module_name}, bin)"),
1242	            &format!("cuModuleLoadData(&{module_name}[dev], bin)"),
1243	        )
1244	        .replace(
1245	            &format!("cuModuleGetFunction(&{function_name}, {module_name}, "),
1246	            &format!("cuModuleGetFunction(&{function_name}[dev], {module_name}[dev], "),
1247	        )
1248	        .replace(
1249	            &format!("cuFuncSetCacheConfig({function_name}, "),
1250	            &format!("cuFuncSetCacheConfig({function_name}[dev], "),
1251	        )
1252	        .replace(
1253	            &format!("cuFuncSetAttribute({function_name}, "),
1254	            &format!("cuFuncSetAttribute({function_name}[dev], "),
1255	        )
1256	        .replace(
1257	            &format!("if ({function_name} == NULL)\n       load_"),
1258	            &format!("CUdevice dev = 0;\n    CUDA_CHECK(pegainfer_triton_current_device(&dev));\n    if ({function_name}[dev] == NULL)\n       load_"),
1259	        )
1260	        .replace(
1261	            &format!("return cuLaunchKernel({function_name}, "),
1262	            &format!("return cuLaunchKernel({function_name}[dev], "),
1263	        )
1264	        .replace(
1265	            "int dev = 0;\n    void *bin =",
1266	            "CUdevice dev = 0;\n    CUDA_CHECK(pegainfer_triton_current_device(&dev));\n    void *bin =",
1267	        );
1268	
1269	    fs::write(c_path, patched).expect("failed to patch generated Triton C source");
1270	}
