1272	fn write_wrapper(generated_c: &Path, file_name: &str, wrapper_src: String) -> PathBuf {
1273	    let wrapper_path = generated_c
1274	        .parent()
1275	        .expect("generated Triton source should have a parent directory")
1276	        .join(file_name);
1277	    std::fs::write(&wrapper_path, wrapper_src).expect("failed to write Triton wrapper source");
1278	    wrapper_path
1279	}
