1571	fn probe_k3_tilelang_python(candidate: &str) -> Result<String, String> {
1572	    let output = Command::new(candidate)
1573	        .args(["-c", "import tilelang"])
1574	        .output()
1575	        .map_err(|err| format!("{candidate}: {err}"))?;
1576	
1577	    if output.status.success() {
1578	        Ok(candidate.to_string())
1579	    } else {
1580	        Err(format!(
1581	            "{candidate}: {}",
1582	            String::from_utf8_lossy(&output.stderr).trim()
1583	        ))
1584	    }
1585	}
