1587	fn find_k3_tilelang_python() -> Result<String, String> {
1588	    for var in ["PEGAINFER_K3_TILELANG_PYTHON", "PEGAINFER_TILELANG_PYTHON"] {
1589	        let Ok(candidate) = std::env::var(var) else {
1590	            continue;
1591	        };
1592	        let candidate = candidate.trim().to_string();
1593	        if candidate.is_empty() {
1594	            return Err(format!("{var} is set but empty."));
1595	        }
1596	        return probe_k3_tilelang_python(&candidate).map_err(|message| {
1597	            format!("{var}=`{candidate}` could not import TileLang: {message}")
1598	        });
1599	    }
1600	
1601	    let local_venv = workspace_root().join("../.venv/bin/python");
1602	    let workspace_venv = workspace_root().join(".venv/bin/python");
1603	    let mut diagnostics = Vec::new();
1604	    let mut candidates = Vec::new();
1605	    if local_venv.exists() {
1606	        candidates.push(local_venv.to_string_lossy().to_string());
1607	    }
1608	    if workspace_venv.exists() {
1609	        candidates.push(workspace_venv.to_string_lossy().to_string());
1610	    }
1611	    candidates.extend(["python3".to_string(), "python".to_string()]);
1612	
1613	    for candidate in candidates {
1614	        match probe_k3_tilelang_python(&candidate) {
1615	            Ok(path) => return Ok(path),
1616	            Err(message) => diagnostics.push(message),
1617	        }
1618	    }
1619	
1620	    Err(format!(
1621	        "Could not find a Python interpreter with TileLang installed. Probe results: {}.",
1622	        diagnostics.join(" | ")
1623	    ))
1624	}
