1626	/// TileLang arch for the AOT lowering. Generation must not depend on a GPU
1627	/// being visible to the build host (containers routinely have none), so the
1628	/// arch is derived from the same SM list nvcc targets and passed explicitly.
1629	/// Architectures from Hopper on need the `a` (accelerated) variant.
1630	fn k3_tilelang_arch(sm_targets: &[String]) -> Option<String> {
1631	    let max_sm = sm_targets
1632	        .iter()
1633	        .filter_map(|sm| sm_numeric_prefix(sm))
1634	        .max()?;
1635	    Some(if max_sm >= 90 {
1636	        format!("sm_{max_sm}a")
1637	    } else {
1638	        format!("sm_{max_sm}")
1639	    })
1640	}
1641	
1642	/// nvcc gencode for the exact arch the TileLang bodies were lowered for.
1643	///
1644	/// These TUs cannot ride the generic arch list: TileLang lowers a TMA copy
1645	/// into a warp-specialized kernel that emits `setmaxnreg`, which ptxas only
1646	/// assembles for the accelerated (`a`) target. Generation targets a single
1647	/// arch, so the objects do too — a multi-SM build gets K3 TileLang kernels for
1648	/// the highest SM only. `None` means this nvcc cannot assemble that arch, and
1649	/// the caller falls back to the stub tier rather than emitting objects that
1650	/// would fail to link or run.
1651	fn k3_tilelang_gencode(arch: &str, nvcc: &str) -> Option<Vec<String>> {
1652	    let target = arch.strip_prefix("sm_")?;
1653	    nvcc_accepts_gencode(nvcc, target, target).then(|| {
1654	        vec![
1655	            "-gencode".to_string(),
1656	            format!("arch=compute_{target},code=sm_{target}"),
1657	        ]
1658	    })
1659	}
