1661	/// Parse the `KEY=VALUE` contract the generator prints on stdout and mirrors
1662	/// into `manifest.txt`: one `CU_PATH` per emitted translation unit, the two
1663	/// header roots the generated CUDA includes, and the arch the bodies were
1664	/// lowered for.
1665	fn parse_k3_tilelang_manifest(text: &str, origin: &str) -> K3TileLangArtifacts {
1666	    let mut cu_files = Vec::new();
1667	    let mut template_include = None;
1668	    let mut cutlass_include = None;
1669	    let mut arch = None;
1670	    for line in text.lines() {
1671	        if let Some(value) = line.strip_prefix("CU_PATH=") {
1672	            cu_files.push(PathBuf::from(value.trim()));
1673	        } else if let Some(value) = line.strip_prefix("TILELANG_TEMPLATE_PATH=") {
1674	            template_include = Some(PathBuf::from(value.trim()));
1675	        } else if let Some(value) = line.strip_prefix("CUTLASS_INCLUDE_DIR=") {
1676	            cutlass_include = Some(PathBuf::from(value.trim()));
1677	        } else if let Some(value) = line.strip_prefix("ARCH=") {
1678	            arch = Some(value.trim().to_string());
1679	        }
1680	    }
1681	
1682	    assert!(!cu_files.is_empty(), "{origin} listed no CU_PATH");
1683	    let template_include =
1684	        template_include.unwrap_or_else(|| panic!("{origin} listed no TILELANG_TEMPLATE_PATH"));
1685	    let cutlass_include =
1686	        cutlass_include.unwrap_or_else(|| panic!("{origin} listed no CUTLASS_INCLUDE_DIR"));
1687	    for cu_file in &cu_files {
1688	        assert!(
1689	            cu_file.exists(),
1690	            "{origin} lists a missing CUDA file: {}",
1691	            cu_file.display()
1692	        );
1693	    }
1694	
1695	    K3TileLangArtifacts {
1696	        cu_files,
1697	        template_include,
1698	        cutlass_include,
1699	        arch,
1700	    }
1701	}
