1703	fn k3_tilelang_pregen_artifacts() -> Option<K3TileLangArtifacts> {
1704	    let dir = std::env::var("PEGAINFER_K3_TILELANG_PREGEN").ok()?;
1705	    let dir = PathBuf::from(dir.trim());
1706	    let manifest = dir.join("manifest.txt");
1707	    let text = fs::read_to_string(&manifest).unwrap_or_else(|err| {
1708	        panic!(
1709	            "PEGAINFER_K3_TILELANG_PREGEN={} has no readable manifest.txt: {err}",
1710	            dir.display()
1711	        )
1712	    });
1713	    println!(
1714	        "cargo:warning=Using pre-generated K3 TileLang CUDA from {}",
1715	        dir.display()
1716	    );
1717	    println!("cargo:rerun-if-changed={}", manifest.display());
1718	    Some(parse_k3_tilelang_manifest(
1719	        &text,
1720	        "PEGAINFER_K3_TILELANG_PREGEN manifest.txt",
1721	    ))
1722	}
