1724	fn generate_k3_tilelang_artifacts(
1725	    out_dir: &Path,
1726	    sm_targets: &[String],
1727	) -> Option<K3TileLangArtifacts> {
1728	    let python = match find_k3_tilelang_python() {
1729	        Ok(python) => python,
1730	        Err(message) => {
1731	            println!("cargo:warning=K3 TileLang generation unavailable: {message}");
1732	            return None;
1733	        }
1734	    };
1735	    let arch = k3_tilelang_arch(sm_targets)?;
1736	
1737	    let generator_path = workspace_root().join("pegainfer-k3/kernels/generate.py");
1738	    assert!(
1739	        generator_path.exists(),
1740	        "K3 TileLang generator is missing: {}",
1741	        generator_path.display()
1742	    );
1743	
1744	    let artifact_dir = out_dir.join("tilelang").join("k3");
1745	    let output = time_phase("tilelang-gen k3", || {
1746	        Command::new(&python)
1747	            .arg(&generator_path)
1748	            .arg("--out-dir")
1749	            .arg(&artifact_dir)
1750	            .arg("--arch")
1751	            .arg(&arch)
1752	            .output()
1753	            .unwrap_or_else(|err| panic!("failed to run the K3 TileLang generator: {err}"))
1754	    });
1755	    assert!(
1756	        output.status.success(),
1757	        "K3 TileLang generator failed. stdout: {} stderr: {}",
1758	        String::from_utf8_lossy(&output.stdout).trim(),
1759	        String::from_utf8_lossy(&output.stderr).trim(),
1760	    );
1761	
1762	    let mut artifacts = parse_k3_tilelang_manifest(
1763	        &String::from_utf8_lossy(&output.stdout),
1764	        "the K3 TileLang generator",
1765	    );
1766	    artifacts.arch.get_or_insert(arch.clone());
1767	    println!("cargo:warning=Generated K3 TileLang CUDA for {arch}");
1768	    println!("cargo:rerun-if-changed={}", generator_path.display());
1769	    println!(
1770	        "cargo:rerun-if-changed={}",
1771	        workspace_root()
1772	            .join("pegainfer-k3/kernels/tilelang_defs.py")
1773	            .display()
1774	    );
1775	    Some(artifacts)
1776	}
