1778	/// Launchers that refuse every shape, for build hosts with neither TileLang
1779	/// nor a pre-generated directory. Keeps the `k3` feature linkable; any decode
1780	/// call fails fast with `cudaErrorNotSupported`.
1781	fn write_k3_tilelang_stub(out_dir: &Path) -> PathBuf {
1782	    let mut source = String::from(
1783	        "// Generated by pegainfer-kernels/build.rs: no K3 TileLang artifacts.\n\
1784	         #include <cuda_runtime.h>\n",
1785	    );
1786	    for (name, params) in K3_TILELANG_LAUNCHERS {
1787	        writeln!(
1788	            source,
1789	            "extern \"C\" int {name}({params}, cudaStream_t) {{\n  \
1790	             return static_cast<int>(cudaErrorNotSupported);\n}}"
1791	        )
1792	        .expect("string write cannot fail");
1793	    }
1794	    let stub_path = out_dir.join("k3_tilelang_stub.cu");
1795	    fs::write(&stub_path, source)
1796	        .unwrap_or_else(|err| panic!("failed to write the K3 TileLang stub: {err}"));
1797	    stub_path
1798	}
