1800	fn k3_tilelang_nvcc_tasks(
1801	    out_dir: &Path,
1802	    cuda_include: &Path,
1803	    arch_args: &[String],
1804	    sm_targets: &[String],
1805	    nvcc: &str,
1806	) -> Vec<NvccTask> {
1807	    println!("cargo:rerun-if-env-changed=PEGAINFER_K3_TILELANG_PYTHON");
1808	    println!("cargo:rerun-if-env-changed=PEGAINFER_K3_TILELANG_PREGEN");
1809	    println!("cargo:rerun-if-env-changed=PEGAINFER_K3_TILELANG_JOBS");
1810	
1811	    let artifacts = k3_tilelang_pregen_artifacts()
1812	        .or_else(|| generate_k3_tilelang_artifacts(out_dir, sm_targets));
1813	
1814	    // Generated bodies need the arch they were lowered for; the stub is plain
1815	    // host code and rides the generic arch list.
1816	    let generated = artifacts.and_then(|artifacts| {
1817	        let arch = artifacts
1818	            .arch
1819	            .clone()
1820	            .or_else(|| k3_tilelang_arch(sm_targets))
1821	            .unwrap_or_default();
1822	        let Some(gencode) = k3_tilelang_gencode(&arch, nvcc) else {
1823	            println!(
1824	                "cargo:warning=nvcc cannot assemble {arch}, which the K3 TileLang bodies were lowered for; they compile as NOT_SUPPORTED stubs"
1825	            );
1826	            return None;
1827	        };
1828	        Some((artifacts, gencode))
1829	    });
1830	
1831	    let (cu_files, extra_includes, tilelang_arch_args) = match generated {
1832	        Some((artifacts, gencode)) => {
1833	            let includes = vec![
1834	                "-I".to_string(),
1835	                artifacts.template_include.to_string_lossy().to_string(),
1836	                "-I".to_string(),
1837	                artifacts.cutlass_include.to_string_lossy().to_string(),
1838	            ];
1839	            (artifacts.cu_files, includes, gencode)
1840	        }
1841	        None => (
1842	            vec![write_k3_tilelang_stub(out_dir)],
1843	            Vec::new(),
1844	            arch_args.to_vec(),
1845	        ),
1846	    };
1847	
1848	    cu_files
1849	        .into_iter()
1850	        .map(|cu_file| {
1851	            let stem = cu_file.file_stem().unwrap().to_str().unwrap();
1852	            let obj_file = out_dir.join(format!("{stem}_cuda.o"));
1853	            let mut args = vec![
1854	                "-c".to_string(),
1855	                cu_file.to_string_lossy().to_string(),
1856	                "-o".to_string(),
1857	                obj_file.to_string_lossy().to_string(),
1858	                "-O3".to_string(),
1859	                "-I".to_string(),
1860	                cuda_include.to_string_lossy().to_string(),
1861	            ];
1862	            args.extend(tilelang_arch_args.iter().cloned());
1863	            args.extend([
1864	                "--std=c++20".to_string(),
1865	                "--compiler-options".to_string(),
1866	                "-fPIC".to_string(),
1867	                // TileLang codegen trips unused-value and narrowing warnings
1868	                // that are noise here; 177 is "declared but never referenced".
1869	                "-w".to_string(),
1870	                "-Xcudafe".to_string(),
1871	                "--diag_suppress=177".to_string(),
1872	            ]);
1873	            args.extend(extra_includes.iter().cloned());
1874	            NvccTask {
1875	                cu_file,
1876	                obj_file,
1877	                args,
1878	            }
1879	        })
1880	        .collect()
1881	}
